MAX_BODY=4_100_000

def _base_schema():
    return {'openapi':'3.1.0','info':{'title':'Stardive private task assurance pilot','version':'0.2'},
      'security':[{'pilotBearer':[]}], 'components':{'securitySchemes':{'pilotBearer':{'type':'http','scheme':'bearer'}}},
      'paths':{
       '/api/tasks':{'post':{'operationId':'freezeTask','summary':'WRITE: Freeze original request, interpreted checklist and selected source bytes BEFORE generating a result','requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False,'required':['request','requirements','sources','artifact_name','artifact_kind','synthetic'],'properties':{'request':{'type':'string','maxLength':10000},'requirements':{'type':'array','minItems':1,'maxItems':100,'items':{'type':'object'}},'sources':{'type':'array','minItems':1,'maxItems':10,'items':{'type':'object','required':['id','name','content_base64'],'properties':{'id':{'type':'string'},'name':{'type':'string'},'content_base64':{'type':'string'}}}},'artifact_name':{'type':'string'},'artifact_kind':{'enum':['text','markdown','json','csv','xlsx','docx']},'synthetic':{'const':True}}}}}},'parameters':[{'in':'header','name':'Idempotency-Key','required':True,'schema':{'type':'string'}}],'responses':{'201':{'description':'Frozen task descriptor and bound inputs'}}}},
       '/api/tasks/{task_id}/versions/{version_id}':{'put':{'operationId':'uploadArtifact','summary':'WRITE: Upload bounded generated bytes as a NEW immutable artifact version; never overwrite','parameters':[{'name':'task_id','in':'path','required':True,'schema':{'type':'string'}},{'name':'version_id','in':'path','required':True,'schema':{'type':'string'}},{'name':'If-Match','in':'header','required':True,'schema':{'type':'string'}}],'requestBody':{'required':True,'content':{'application/octet-stream':{'schema':{'type':'string','format':'binary'}}}},'responses':{'201':{'description':'Exact artifact binding'}}}},
       '/api/tasks/{task_id}/receipts':{'post':{'operationId':'saveVerificationReceipt','summary':'WRITE: Independently verify and save an audit receipt; does not complete or release the result','parameters':[{'name':'task_id','in':'path','required':True,'schema':{'type':'string'}}],'requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False,'required':['version_id'],'properties':{'version_id':{'type':'string'}}}}}},'responses':{'201':{'description':'Compact view, result and details links'}}}},
       '/api/tasks/{task_id}':{'get':{'operationId':'getFrozenTask','summary':'READ: Inspect original task; no state change','parameters':[{'name':'task_id','in':'path','required':True,'schema':{'type':'string'}}],'responses':{'200':{'description':'Frozen task descriptor'}}}},
       '/api/tasks/{task_id}/receipts/{receipt_ref}':{'get':{'operationId':'getReceiptDetails','summary':'READ: Original historical receipt; does not establish current validity','parameters':[{'name':n,'in':'path','required':True,'schema':{'type':'string'}} for n in ('task_id','receipt_ref')],'responses':{'200':{'description':'Machine receipt'}}}},
       '/api/tasks/{task_id}/receipts/{receipt_ref}/result':{'get':{'operationId':'downloadReviewedResult','summary':'READ: Release exact verified bytes only after current receipt-required completion','parameters':[{'name':n,'in':'path','required':True,'schema':{'type':'string'}} for n in ('task_id','receipt_ref')],'responses':{'200':{'description':'Immutable artifact bytes'}}}}},
      'x-pilot-limits':{'synthetic_only':True,'source_bytes_each':MAX_UPLOAD,'artifact_bytes':MAX_UPLOAD,'body_bytes':MAX_BODY,'mcp':'POST /mcp; three read-only tools. No intake, upload, receipt save or repair tool in MCP.',
        'normal_use':'Connector integration owns technical IDs internally: freeze -> generate -> upload new version -> review -> save fresh receipt -> complete -> download -> return useful result, checked-value table, inline receipt. No automatic invocation is established by this specification.'}}


def schema(public_base_url=None,data_policy="synthetic_only",max_stored_bytes_per_owner=256*1024*1024):
    from ..taskflow.config_schemas import schemas,requirement_schema
    result=_base_schema()
    result['paths']['/api/tasks/{task_id}/complete']={'post':{'operationId':'completeVerifiedTask','summary':'WRITE: Complete only with an intact stored passing receipt for the active version; rechecks every frozen condition','requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','additionalProperties':False,'required':['receipt_ref'],'properties':{'receipt_ref':{'type':'string'}}}}}},'responses':{'200':{'description':'COMPLETED; canonical result release enabled'},'409':{'description':'BLOCKED; missing, failed, unknown, stale or invalid verification'}}}}
    result['paths']['/api/tasks/{task_id}/completion']={'get':{'operationId':'getCompletionStatus','summary':'READ: Revalidate current server completion; never infer completion from a saved audit','responses':{'200':{'description':'Current COMPLETED or BLOCKED status'}}}}
    for path in ('/api/tasks/{task_id}/complete','/api/tasks/{task_id}/completion'):
        for operation in result['paths'][path].values():operation['parameters']=[{'name':'task_id','in':'path','required':True,'schema':{'type':'string'}}]
    result['x-completion-policy']={'required':True,'scope':'Backend completion state and canonical result delivery only; Muse final chat responses have no host veto','flow':'freeze -> generate -> upload -> review -> save receipt -> POST complete with receipt_ref -> download result','blocks':['missing receipt','FAIL','UNKNOWN','BLOCKED','STALE','unsupported checklist','changed evidence','newer uploaded version'],'legacy_receipts':'Historical only; fresh receipt required before completion'}
    selected=data_policy=='selected_task_inputs'
    props=result['paths']['/api/tasks']['post']['requestBody']['content']['application/json']['schema']['properties']
    props['synthetic']={'type':'boolean','description':'Caller declaration only, not a data detector. False means selected current-task inputs.'}
    if not selected:props['synthetic']['const']=True
    result['x-pilot-limits'].update(synthetic_only=not selected,data_policy=data_policy,max_stored_bytes_per_owner=max_stored_bytes_per_owner,stored_bytes_basis='Actual regular-file bytes including retained copies and staged writes; single-worker owner lock. No prior-data deletion.')
    result['components']['schemas']={'TaskflowRequirement':requirement_schema()}
    result['paths']['/api/tasks']['post']['requestBody']['content']['application/json']['schema']['properties']['requirements']['items']={'$ref':'#/components/schemas/TaskflowRequirement'}
    result['x-checker-config-schemas']=schemas()
    result['x-credential-setup']={'scheme':'api_key','placement':'bearer_header','api_hosts':[urlsplit(public_base_url).hostname] if public_base_url else [],'state':'configured origin only; registration untested' if public_base_url else 'hosting unconfigured','exchange':'Muse hosted secure credential connection; brokered surrogate; no credential in helper files/arguments/logs; disable authenticated redirects'}
    if public_base_url:result['servers']=[{'url':public_base_url.rstrip('/')} ]
    result['x-config-policy']='Exact supported configurations only. Native intake rejects unknown extra fields for these kinds; independent existing task review returns UNKNOWN. Unknown kinds remain unresolved.'
    return result


def create_app(config):
    pilot=Pilot(config);servers={};owner_apps={}
    for owner in {c.principal for c in config.credentials}:
        server=FastMCP('Stardive private task assurance',instructions='Review only the declared current-task conditions within the launch data policy. Input classification is caller-declared, not detected. No writes, generation, arbitrary commands, URL fetching or global certification.',
          stateless_http=True,json_response=True,log_level='WARNING',max_request_body_size=MAX_BODY,
          transport_security=TransportSecuritySettings(enable_dns_rebinding_protection=True,allowed_hosts=['127.0.0.1:*','localhost:*']+([urlsplit(config.public_base_url).netloc] if config.public_base_url else []),allowed_origins=list(config.origins)))
        readonly=ToolAnnotations(readOnlyHint=True,destructiveHint=False,idempotentHint=True,openWorldHint=False)
        # Factory closures bind owner at launch, never from tool arguments.
        def install(s,principal):
            @s.tool(annotations=readonly)
            def taskflow_capabilities()->dict:
                from ..taskflow.checks import SUPPORTED_KINDS
                from ..taskflow.config_schemas import schemas
                return {'supported':sorted(SUPPORTED_KINDS),'config_schemas':schemas(),'config_policy':'Exact fields; unsupported mappings abstain, never partial PASS','read_only':True,'synthetic_only':config.data_policy=='synthetic_only','data_policy':config.data_policy,'classification_basis':'Caller synthetic boolean is a declaration, not a detector; false remains selected current-task input','limits':{'max_stored_bytes_per_owner':config.max_stored_bytes_per_owner,'accounting':'All retained owner files, copies, metadata and projected staged writes; quota rejections never evict prior data'},'unknown':['semantic truth','privacy','provider state','sent/delivered claims','checklist completeness','source authenticity'],'completion_required':True,'completion_scope':'Backend completion and canonical delivery; no Muse host final-response veto','writes':'Intake, upload, verification receipt persistence and mandatory completion are separate authenticated HTTP writes.'}
            @s.tool(annotations=readonly)
            def taskflow_review(task_id:str,version_id:str)->dict:
                """Execute comparisons on current owner-authorized version bytes, without saving state."""
                return pilot.review(principal,task_id,version_id)
            @s.tool(annotations=readonly)
            def taskflow_recheck(task_id:str,version_id:str,prior_receipt:dict)->dict:
                """Recompute current checks and compare old bindings; supplied assertions never become proof."""
                return pilot.recheck(principal,task_id,version_id,prior_receipt)
        install(server,owner);servers[owner]=server
        mcp=server.streamable_http_app()
        async def endpoint(request):
            cred=request.scope['state']['credential'];principal=cred.principal
            path=request.url.path;method=request.method
            required='review' if method=='GET' else 'intake' if path=='/api/tasks' else 'artifact' if '/versions/' in path else 'receipt'
            if required not in cred.scopes:return JSONResponse({'error':'Scope not granted'},status_code=403)
            try:
                if method=='POST' and request.headers.get('content-type','').split(';')[0]!='application/json':return JSONResponse({'error':'application/json required'},status_code=415)
                if path=='/openapi.json':return JSONResponse(schema(config.public_base_url,config.data_policy,config.max_stored_bytes_per_owner))
                if path=='/api/tasks':
                    body=strict_json(await request.body());result=await asyncio.to_thread(pilot.create,principal,body,request.headers.get('idempotency-key'));return JSONResponse(result,status_code=201)
                task_id=request.path_params['task_id']
                if method=='PUT':
                    if request.headers.get('content-type','').split(';')[0]!='application/octet-stream':return JSONResponse({'error':'Raw application/octet-stream required'},status_code=415)
                    result=await asyncio.to_thread(pilot.upload,principal,task_id,await request.body(),request.headers.get('if-match'),request.path_params['version_id']);return JSONResponse(result,status_code=201)
                if path.endswith('/completion'):
                    return JSONResponse(await asyncio.to_thread(pilot.completion,principal,task_id))
                if method=='POST' and path.endswith('/complete'):
                    body=strict_json(await request.body())
                    if not isinstance(body,dict) or set(body)!={'receipt_ref'}:raise ValueError('Only a stored receipt_ref accepted')
                    return JSONResponse(await asyncio.to_thread(pilot.complete,principal,task_id,body['receipt_ref']))
                if path.endswith('/result'):
                    artifact,data=await asyncio.to_thread(pilot.release,principal,task_id,request.path_params['receipt_ref'])
                    return Response(data,media_type='application/octet-stream',headers={'Content-Disposition':f'attachment; filename="{artifact}"'})
                if method=='POST':
                    body=strict_json(await request.body())
                    if not isinstance(body,dict) or set(body)!={'version_id'}:raise ValueError('Only version_id accepted; caller receipts or verdicts cannot be saved')
                    result=await asyncio.to_thread(pilot.persist,principal,task_id,body['version_id']);return JSONResponse({k:v for k,v in result.items() if k!='receipt'},status_code=201)
                if 'receipt_ref' not in request.path_params:return JSONResponse(pilot.describe(principal,task_id))
                ref=request.path_params['receipt_ref']
                if not ref.startswith('receipt-') or not ID_RE.fullmatch(ref):raise ValueError('Receipt reference refused')
                task=pilot.task(principal,task_id);folder=task/'pilot-receipts'/ref
                from ..io import safe_path
                file=safe_path(task,'pilot-receipts/'+ref+'/receipt.json')
                receipt=strict_json(file.read_bytes())
                return JSONResponse(receipt)
            except (Conflict,QuotaExceeded) as e:return JSONResponse({'state':'BLOCKED','error':str(e)},status_code=409)
            except (ValueError,KeyError,TypeError,OSError,UnicodeError):return JSONResponse({'error':'Input refused, unavailable, or outside authorized scope'},status_code=400)
        routes=[Route('/openapi.json',endpoint,methods=['GET']),Route('/api/tasks',endpoint,methods=['POST']),Route('/api/tasks/{task_id}',endpoint,methods=['GET']),Route('/api/tasks/{task_id}/versions/{version_id}',endpoint,methods=['PUT']),Route('/api/tasks/{task_id}/receipts',endpoint,methods=['POST']),Route('/api/tasks/{task_id}/complete',endpoint,methods=['POST']),Route('/api/tasks/{task_id}/completion',endpoint,methods=['GET']),Route('/api/tasks/{task_id}/receipts/{receipt_ref}/result',endpoint,methods=['GET']),Route('/api/tasks/{task_id}/receipts/{receipt_ref}',endpoint,methods=['GET']),Mount('/',app=mcp)]
        owner_apps[owner]=Starlette(routes=routes)
    @asynccontextmanager
    async def lifespan(app):
        async with AsyncExitStack() as stack:
            for server in servers.values():await stack.enter_async_context(server.session_manager.run())
            yield
    top=Starlette(lifespan=lifespan)
    class Gateway:
        def __init__(self):self.pilot=pilot;self.top=top;self.buckets={};self.active=asyncio.Semaphore(4)
        async def __call__(self,scope,receive,send):
            if scope['type']=='lifespan':return await top(scope,receive,send)
            if scope['type']!='http':return
            response=None;headers={}
            for key,val in scope['headers']:
                name=key.decode().lower()
                if name in headers and name in ('authorization','host','content-length','origin'):response=JSONResponse({'error':'Ambiguous headers'},status_code=400)
                headers[name]=val.decode()
            host=headers.get('host','');allowed={'localhost','127.0.0.1'}
            if config.public_base_url:allowed.add(urlsplit(config.public_base_url).hostname)
            if host.split(':')[0] not in allowed:response=JSONResponse({'error':'Host refused'},status_code=400)
            if 'origin' in headers and headers['origin'] not in config.origins:response=JSONResponse({'error':'Origin refused'},status_code=403)
            auth=headers.get('authorization','');cred=config.authenticate(auth[7:]) if auth.startswith('Bearer ') else None
            if not cred:response=JSONResponse({'error':'Authentication required'},status_code=401,headers={'WWW-Authenticate':'Bearer realm="stardive-private-pilot"'})
            if response:return await response(scope,receive,send)
            if scope['path'].startswith('/mcp') and 'review' not in cred.scopes:return await JSONResponse({'error':'Review scope required'},status_code=403)(scope,receive,send)
            minute=int(time.monotonic()//60);bucket=self.buckets.get(cred.principal,(minute,0));count=bucket[1]+1 if bucket[0]==minute else 1;self.buckets[cred.principal]=(minute,count)
            if count>config.requests_per_minute:return await JSONResponse({'error':'Pilot rate limit'},status_code=429,headers={'Retry-After':'60'})(scope,receive,send)
            data=bytearray()
            try:
                async with asyncio.timeout(20):
                    while True:
                        event=await receive()
                        if event['type']=='http.disconnect':return
                        data.extend(event.get('body',b''))
                        if len(data)>MAX_BODY:return await JSONResponse({'error':'Upload limit exceeded'},status_code=413)(scope,receive,send)
                        if not event.get('more_body'):break
            except TimeoutError:return await JSONResponse({'error':'Upload timed out'},status_code=408)(scope,receive,send)
            scope['state']={**scope.get('state',{}),'credential':cred}
            sent=False
            async def replay():
                nonlocal sent
                if not sent:sent=True;return {'type':'http.request','body':bytes(data),'more_body':False}
                return await receive()
            async with self.active:
                return await owner_apps[cred.principal](scope,replay,send)
    return Gateway()
